 21→	let loading = $state(true);
 22→	let error = $state('');
 23→
 24→	// ── Filter state ──
 25→	type PlanStatusFilter = 'all' | 'draft' | 'approved' | 'active' | 'completed' | 'rejected';
 26→	let filterStatus = $state<PlanStatusFilter>('all');
 27→
 28→	// ── Plan status labels and colors ──
 29→	// AC: @ui-plans-view ac-1 — visually distinct statuses with text labels
 30→	const PLAN_STATUS_LABELS: Record<string, string> = {
 31→		draft: 'Draft',
 32→		approved: 'Approved',
 33→		active: 'Active',
 34→		completed: 'Completed',
 35→		rejected: 'Rejected'
 36→	};
 37→
 38→	const PLAN_STATUS_COLORS: Record<string, string> = {
 39→		draft: 'bg-status-pending text-status-pending-fg',
 40→		approved: 'bg-status-pending-review text-status-pending-review-fg',
 41→		active: 'bg-status-in-progress text-status-in-progress-fg',
 42→		completed: 'bg-status-completed text-status-completed-fg',
 43→		rejected: 'bg-status-blocked text-status-blocked-fg'
 44→	};
 45→
 46→	// ── Filtered plans ──
 47→	let filteredPlans = $derived.by(() => {
 48→		if (filterStatus === 'all') return plans;
 49→		return plans.filter((p) => p.status === filterStatus);
 50→	});
 51→
 52→	// ── Status summary counts ──
 53→	let statusCounts = $derived.by(() => {
 54→		const counts: Record<string, number> = {};
